import sys
from collections import defaultdict

def z_function(s):
    n = len(s)
    z = [0] * n
    l, r = 0, 0
    for i in range(1, n):
        if i <= r:
            z[i] = min(r - i + 1, z[i - l])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] - 1 > r:
            l, r = i, i + z[i] - 1
    return z

def self_similarity(s):
    n = len(s)
    total = 0
    for i in range(n):
        z = z_function(s[i:])
        for val in z:
            total += val
    return total

def main():
    import sys
    input = sys.stdin.read().splitlines()
    T = int(input[0])
    results = []
    for i in range(1, T + 1):
        s = input[i]
        results.append(str(self_similarity(s)))
    print("\n".join(results))

if __name__ == "__main__":
    main()
